insert into public.vertice_settings(id,payload) values(1,'{"name":"Vértice Motors","address":"Av. Horizonte, 1200 · São Paulo, SP (endereço fictício)","hours":"Segunda a sexta, 9h–18h · Sábado, 9h–14h","email":"contato@vertice.example","whatsapp":"","story":"Acreditamos que escolher um carro é escolher o que vem depois. A Vértice nasceu para tornar essa decisão mais clara: informações que você entende, tempo para conhecer cada detalhe e uma conversa sem pressa. Esta é uma loja fictícia criada para demonstrar uma experiência de compra mais cuidadosa."}'::jsonb) on conflict(id) do nothing;
